from auto_config.generator.gnb.managed_objects.managed_object import ManagedObject


class NrcellgrpParamsGenerator(ManagedObject):

    def __init__(self, *args, **kwargs):
        super().__init__(*args, **kwargs)
        self.cell_ent = self.enb_ent_config['cells'][self.cell_num]

    def _prepare_section_content(self, execution_config, *args, **kwargs):
        self.set_parameter('scs', self.cell_ent['scs'])
        self.set_parameter('nrCellList', self.mo_num)
        self.set_optional(execution_config)
        if not self.is_ecpri_72a(self.mo_num):
            self.set_params_ecpri_72e()

    def set_params_ecpri_72e(self):
        self.set_parameter('numberOfTransmittedSsBlocks', '2 beams')

    def set_optional(self, execution_config):
        self.set_parameter('numberOfTransmittedSsBlocks', '6 beams')
        if execution_config['release'] >= 25.1:
            self.set_parameter('actPucchBeamConstraintFR2', 'false')
        self.set_parameter('maxNumOfNonGBRBearers', '1280')
        self.set_parameter('maxNumOfNonGBRBearersCGRPSA', '1280')
        self.set_parameter('maxNumOfRrcCGRPSA', '640')
        self.set_parameter('maxNumOfUsers', '1280')
